package passport

import (
	"encoding/hex"
	"strings"
	"testing"
)

// Generated by Defuse\Crypto\Crypto::encryptWithPassword(
// "m1-passport-vector", "m1-test-password") under the frozen vendor.
const defuseGolden = "def502000b663768066d711999e1365ea229d3145f4826eb1db500672a133bb1ff22f5afebfde73e6b5cf6987e76206a6b9b374125f1a70ba9fbbb235ae0341053eb2dec02ae15c5b23943833f1bbbdf94f47fe55f6719dbe33f7e68dab990e4b3e4f6385975"

func TestDecryptPHPDefuseVector(t *testing.T) {
	plaintext, err := DecryptWithPassword(defuseGolden, []byte("m1-test-password"))
	if err != nil {
		t.Fatal(err)
	}
	if plaintext != "m1-passport-vector" {
		t.Fatalf("plaintext = %q", plaintext)
	}
}

func TestDefuseRoundTrip(t *testing.T) {
	for _, value := range []string{"", "a", "refresh-token-payload", strings.Repeat("x", 1024)} {
		ciphertext, err := EncryptWithPassword(value, []byte("another-password"))
		if err != nil {
			t.Fatal(err)
		}
		decoded, err := DecryptWithPassword(ciphertext, []byte("another-password"))
		if err != nil {
			t.Fatal(err)
		}
		if decoded != value {
			t.Fatalf("round trip = %q, want %q", decoded, value)
		}
	}
}

func TestDefuseRejectsTampering(t *testing.T) {
	raw, _ := hex.DecodeString(defuseGolden)

	badMAC := append([]byte(nil), raw...)
	badMAC[len(badMAC)-1] ^= 0x01
	if _, err := DecryptWithPassword(hex.EncodeToString(badMAC), []byte("m1-test-password")); err == nil {
		t.Fatal("modified MAC accepted")
	}

	badHeader := append([]byte(nil), raw...)
	badHeader[1] ^= 0x01
	if _, err := DecryptWithPassword(hex.EncodeToString(badHeader), []byte("m1-test-password")); err == nil {
		t.Fatal("modified header accepted")
	}

	if _, err := DecryptWithPassword(defuseGolden, []byte("wrong-password")); err == nil {
		t.Fatal("wrong password accepted")
	}
	if _, err := DecryptWithPassword("not-hex", []byte("m1-test-password")); err == nil {
		t.Fatal("non-hex accepted")
	}
}
